using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using SistemPengurusanKehadiran.Services;namespace SistemPengurusanKehadiran.Pages;public sealed partial class SettingsPage:Page{public SettingsPage(){InitializeComponent();Loaded+=(_,_)=>Load();}void Load(){var p=DatabaseService.Instance.GetSchoolProfile();SchoolName.Text=p.Name;SchoolCode.Text=p.Code;SchoolId.Text="School ID: "+DatabaseService.Instance.SchoolId;DbPath.Text="SQLite: "+DatabaseService.Instance.DatabasePath;Pending.Text=$"Pending sync: {DatabaseService.Instance.PendingSyncCount()} · Konflik: {DatabaseService.Instance.ConflictCount()}";}void Save_Click(object s,RoutedEventArgs e){DatabaseService.Instance.SaveSchoolProfile(SchoolName.Text,SchoolCode.Text);Load();}}
